-- 【给前端同学】SQL 脚本 ≈ 「数据表的结构定义」，相当于前端给数组里每个元素定好字段类型。
-- 这个文件由 application.yml 的 spring.sql.init.schema-locations 在**每次启动时自动执行**。
-- -- 开头是 SQL 注释；DDL 指 CREATE TABLE 这类「建结构」的语句。

-- IF NOT EXISTS：表已存在就跳过，避免重复执行报错（≈ 前端「有则复用，没有才创建」）
CREATE TABLE IF NOT EXISTS students (   -- 表名 students，对应 Java 的 entity/Student.java
  id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  -- ↑ id：BIGINT 大整数；GENERATED BY DEFAULT AS IDENTITY = H2 的「自增」写法；
  --   PRIMARY KEY 主键 = 每行唯一标识，≈ 前端 row.id，编辑/删除时拼在 URL /api/students/{id} 上。
  --   插入时不写 id，数据库自动分配；XML 的 useGeneratedKeys 会把这个值回填给 Java 对象。
  --   注意：MySQL 里同一件事写成 AUTO_INCREMENT，见 schema-mysql.sql（这叫「数据库方言差异」）
  name       VARCHAR(50) NOT NULL,   -- 姓名：最长 50 字符的可变字符串；NOT NULL = 必填
  age        INT         NOT NULL,   -- 年龄：整数，必填
  class_name VARCHAR(50) NOT NULL,  -- 班级：★ 列名用下划线 class_name，
                                    --   靠 application.yml 的 map-underscore-to-camel-case 映射成前端的 className
  phone      VARCHAR(20) NOT NULL   -- 电话：用字符串而不是数字，因为手机号可能有前导 0 / +86，且不做数学运算
);
-- 这里的 NOT NULL 是数据库层的最后一道防线；
-- 在此之前还有前端 StudentForm.vue 的 rules 和后端 StudentRequest 的 @NotBlank 两道校验。
